from pathlib import Path
ROOT=Path('/home/enpasos/projects/skillpilot');OUT=Path(__file__).resolve().parent
def load(n):return json.loads((OUT/n).read_text())
def bind(p):
 p=Path(p);p=p if p.is_absolute() else ROOT/p;b=p.read_bytes();return {'path':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'symlink':p.is_symlink()}
def save(n,o):
 p=OUT/n;assert not p.exists();p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n');return bind(p)
